#include <algorithm>
#include <cstdint>
#include <iostream>
#include <utility>
#include <vector>

using namespace std;

const int MOD = 1000000007;

int mod_pow(int base, int exponent) {
    long long result = 1;
    long long factor = base;
    while (exponent > 0) {
        if (exponent & 1) result = result * factor % MOD;
        factor = factor * factor % MOD;
        exponent >>= 1;
    }
    return static_cast<int>(result);
}

int binomial(int total, int chosen, const vector<int>& factorial,
             const vector<int>& inverse_factorial) {
    if (chosen < 0 || chosen > total) return 0;
    long long result = factorial[total];
    result = result * inverse_factorial[chosen] % MOD;
    result = result * inverse_factorial[total - chosen] % MOD;
    return static_cast<int>(result);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    if (!(cin >> n >> m)) return 0;

    vector<pair<int, int>> obstacles;
    obstacles.reserve(static_cast<size_t>(m));
    for (int i = 0; i < m; ++i) {
        int row, col;
        cin >> row >> col;
        obstacles.emplace_back(row, col);
    }

    sort(obstacles.begin(), obstacles.end());
    obstacles.erase(unique(obstacles.begin(), obstacles.end()), obstacles.end());

    const pair<int, int> start{0, 0};
    const pair<int, int> destination{n - 1, n - 1};
    if (binary_search(obstacles.begin(), obstacles.end(), start) ||
        binary_search(obstacles.begin(), obstacles.end(), destination)) {
        cout << 0 << '\n';
        return 0;
    }
    if (n == 1) {
        cout << 1 << '\n';
        return 0;
    }

    const uint64_t obstacle_count = static_cast<uint64_t>(obstacles.size());
    const uint64_t sparse_pair_work = obstacle_count * (obstacle_count + 1) / 2;
    const uint64_t dense_cell_work = static_cast<uint64_t>(n) * n;

    // Use the pairwise method only when its estimated work is far below the dense scan.
    if (sparse_pair_work <= dense_cell_work / 1024) {
        const int max_path_length = 2 * n - 2;
        vector<int> factorial(static_cast<size_t>(max_path_length) + 1);
        vector<int> inverse_factorial(static_cast<size_t>(max_path_length) + 1);
        factorial[0] = 1;
        for (int i = 1; i <= max_path_length; ++i) {
            factorial[i] = static_cast<long long>(factorial[i - 1]) * i % MOD;
        }
        inverse_factorial[max_path_length] =
            mod_pow(factorial[max_path_length], MOD - 2);
        for (int i = max_path_length; i > 0; --i) {
            inverse_factorial[i - 1] =
                static_cast<long long>(inverse_factorial[i]) * i % MOD;
        }

        vector<int> ways_to_obstacle(obstacles.size());
        for (size_t i = 0; i < obstacles.size(); ++i) {
            const int row = obstacles[i].first;
            const int col = obstacles[i].second;
            int ways = binomial(row + col, row, factorial, inverse_factorial);

            for (size_t j = 0; j < i; ++j) {
                const int prev_row = obstacles[j].first;
                const int prev_col = obstacles[j].second;
                if (prev_row > row || prev_col > col) continue;

                const int segment_paths = binomial(
                    (row - prev_row) + (col - prev_col), row - prev_row,
                    factorial, inverse_factorial);
                const int paths_through_previous =
                    static_cast<long long>(ways_to_obstacle[j]) * segment_paths % MOD;
                ways -= paths_through_previous;
                if (ways < 0) ways += MOD;
            }
            ways_to_obstacle[i] = ways;
        }

        int answer = binomial(2 * n - 2, n - 1, factorial, inverse_factorial);
        for (size_t i = 0; i < obstacles.size(); ++i) {
            const int row = obstacles[i].first;
            const int col = obstacles[i].second;
            const int segment_paths = binomial(
                (n - 1 - row) + (n - 1 - col), n - 1 - row,
                factorial, inverse_factorial);
            const int paths_through_obstacle =
                static_cast<long long>(ways_to_obstacle[i]) * segment_paths % MOD;
            answer -= paths_through_obstacle;
            if (answer < 0) answer += MOD;
        }
        cout << answer << '\n';
        return 0;
    }

    // Dense fallback: keep only one contiguous DP row and stream obstacles in row-major order.
    vector<int> dp(n, 0);
    size_t obstacle_index = 0;
    for (int row = 0; row < n; ++row) {
        for (int col = 0; col < n; ++col) {
            const bool blocked = obstacle_index < obstacles.size() &&
                                 obstacles[obstacle_index].first == row &&
                                 obstacles[obstacle_index].second == col;
            if (blocked) ++obstacle_index;

            int ways = (row == 0 && col == 0) ? 1 : 0;
            if (row > 0) ways += dp[col];
            if (col > 0) ways += dp[col - 1];
            if (ways >= MOD) ways -= MOD;
            dp[col] = blocked ? 0 : ways;
        }
    }

    cout << dp[n - 1] << '\n';
    return 0;
}
